select jsonb_build_object(
 'migrations',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations where version in ('20260813132950','20260813135311')),
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'public',coalesce(has_function_privilege('public',p.oid,'execute'),false),'anon',coalesce(has_function_privilege('anon',p.oid,'execute'),false),'authenticated',coalesce(has_function_privilege('authenticated',p.oid,'execute'),false),'config',p.proconfig) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('crew_leave_days_in_period','crew_leave_entitlement_balance','crew_leave_ensure_entitlement','crew_leave_submit','crew_leave_mobile','crew_leave_admin_data','crew_leave_policy_save','crew_leave_adjust','crew_leave_review')),
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'anon_select',has_table_privilege('anon',c.oid,'select'),'authenticated_select',has_table_privilege('authenticated',c.oid,'select'),'authenticated_insert',has_table_privilege('authenticated',c.oid,'insert'),'authenticated_update',has_table_privilege('authenticated',c.oid,'update')) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('crew_leave_policies','crew_leave_entitlements','crew_leave_adjustments'))
) crew_leave_entitlement_security;
